    try{if(mode==='source_backed'&&(preview?._signature!==querySignature||queryEdited))await saveQuery(queryEdited);const queued=await apiRequest<{job_id:string;status:string}>(`/scenario-plans/${plan.id}/generate`,role,{method:'POST',body:JSON.stringify({confirm_source_extraction:mode==='source_backed'&&confirmExtraction,dataset_name:datasetName,target_use:targetUse,maximum_records:volume,output_format:outputFormat,expiry_at:expiry?new Date(expiry).toISOString():null,draft_dataset_id:draftDatasetId||undefined})});setPlan(current=>current?{...current,state:'running',job:{id:queued.job_id,status:queued.status,progress:0,safe_summary:'Generation queued'}}:current);await refreshPlan();setNotice('Generation started. Job state will update here.')}
    catch(err){setError(message(err))}finally{setBusy(false)}
