    setBusy(true);setError('');setNotice('');setMapping([]);setSourceObject('');setSourceJoins([]);setFilters([]);setRelationships([]);setQueryText('');setQueryEdited(false);setQueryRepair(null);setQueryError('');setQueryNotice('');setPreview(null)
    setPlan(current=>current?{...current,state:'draft',mapping:[],suggested_mapping:[],logical_plan:{...current.logical_plan,predicates:[],relationships:[],source_joins:[],suggested_source_joins:[],suggested_filters:[],schema_generation_notes:[],requirement_intent:undefined,criteria_coverage:[],schema_generation_feedback:schemaFeedback,generated_query:undefined,generated_query_fields:undefined,generated_query_field_types:undefined}}:current)
    try{const saved=await apiRequest<Plan>(`/scenario-plans/${plan.id}/schema`,role,{method:'POST',body:JSON.stringify({generation_mode:mode,source_connection_id:mode==='source_backed'?sourceId:null,selected_source_objects:mode==='source_backed'?selectedSourceObjects:[],feedback:schemaFeedback})});setPlan(saved);setSchemaFeedback(saved.logical_plan.schema_generation_feedback??schemaFeedback);setMapping(mode==='source_backed'?[]:saved.mapping.map(field=>({...field,required:true})));setSourceObject(saved.source_object??'');setSourceJoins([]);setFilters([]);setQueryText('');setQueryEdited(false);setPreview(null);setDatasetName(current=>current||saved.name);setVolume(saved.volume)}
